insert into public.ingredients (name, slug, description, category, image_url, storage_information, safety_information, status)
values
  ('Red lentils', 'red-lentils', 'Split red lentils soften quickly and thicken soups and stews.', 'Legumes', null, 'Keep dry lentils in a sealed container in a cool, dry cupboard.', 'Sort and rinse dry lentils before cooking; follow package directions and cook until tender.', 'published'),
  ('Green lentils', 'green-lentils', 'Green lentils hold their shape well when simmered gently.', 'Legumes', null, 'Keep dry lentils sealed in a cool, dry cupboard.', 'Sort and rinse dry lentils before cooking; cook until tender.', 'published'),
  ('Chickpeas', 'chickpeas', 'Chickpeas add a creamy texture and mild, nutty flavor to many dishes.', 'Legumes', null, 'Store dry chickpeas in a sealed cool, dry place; refrigerate opened canned chickpeas in a covered container.', 'Drain and rinse canned chickpeas with clean water; cook dried chickpeas fully.', 'published'),
  ('Dried pasta', 'dried-pasta', 'Dried wheat pasta cooks in salted water and pairs with many sauces.', 'Grains', null, 'Keep in its sealed package or an airtight container in a dry cupboard.', 'Check the package for wheat or other allergen information.', 'published'),
  ('Basmati rice', 'basmati-rice', 'Basmati is a long-grain rice known for a light, aromatic finish.', 'Grains', null, 'Store uncooked rice in a dry, sealed container.', 'Rinse if desired and cook using package guidance; refrigerate cooked rice promptly.', 'published'),
  ('Canned tomatoes', 'canned-tomatoes', 'Canned tomatoes provide a consistent base for sauces, stews, and braises.', 'Vegetables', null, 'Store unopened cans in a cool, dry cupboard; refrigerate leftovers in a covered container.', 'Discard leaking, bulging, or badly damaged cans.', 'published'),
  ('Ripe tomatoes', 'ripe-tomatoes', 'Fresh tomatoes bring acidity and juiciness to salads and cooked dishes.', 'Vegetables', null, 'Keep ripe tomatoes at room temperature for best texture; refrigerate cut tomatoes.', 'Wash under running water before cutting.', 'published'),
  ('Red onion', 'red-onion', 'Red onion is useful raw for sharpness and cooked for mellow sweetness.', 'Vegetables', null, 'Store whole onions in a cool, dry, ventilated place; refrigerate cut onion in a covered container.', 'Wash hands and cutting surfaces after handling produce.', 'published'),
  ('Garlic', 'garlic', 'Garlic contributes a savory aroma and can become bitter if scorched.', 'Aromatics', null, 'Store whole bulbs in a cool, dry place with airflow.', 'Use clean utensils and refrigerate prepared garlic mixtures promptly.', 'published'),
  ('Fresh ginger', 'fresh-ginger', 'Fresh ginger adds warm, citrusy aroma to sauces, soups, and stir-fries.', 'Aromatics', null, 'Refrigerate fresh ginger in a breathable bag or covered container.', 'Wash before peeling or cutting.', 'published'),
  ('Red bell pepper', 'red-bell-pepper', 'Red bell pepper adds sweetness, color, and a crisp bite.', 'Vegetables', null, 'Refrigerate whole peppers and use cut pepper within a few days.', 'Wash under running water before cutting.', 'published'),
  ('Baby spinach', 'baby-spinach', 'Tender spinach wilts quickly and works in soups, curries, and egg dishes.', 'Vegetables', null, 'Keep refrigerated and follow the package use-by guidance.', 'Wash loose leaves under running water; follow package instructions for ready-to-eat greens.', 'published'),
  ('Eggs', 'eggs', 'Eggs set into a tender protein-rich curd when gently cooked.', 'Protein', null, 'Keep eggs refrigerated in their carton.', 'Keep eggs refrigerated and cook until whites and yolks are firm unless using pasteurized eggs in a preparation that remains raw.', 'published'),
  ('Chicken thighs', 'chicken-thighs', 'Chicken thighs stay moist when cooked thoroughly and suit quick sautés or braises.', 'Poultry', null, 'Keep raw chicken refrigerated at 4 C / 40 F or below and separate from ready-to-eat food.', 'Use separate utensils and surfaces for raw poultry; cook to 74 C / 165 F measured with a food thermometer.', 'published'),
  ('Olive oil', 'olive-oil', 'Olive oil carries aromas and helps ingredients cook evenly.', 'Pantry', null, 'Store tightly closed away from heat and direct light.', 'Avoid leaving hot oil unattended; keep water away from hot oil.', 'published'),
  ('Ground cumin', 'ground-cumin', 'Cumin has an earthy aroma and is used in many regional cooking traditions.', 'Spices', null, 'Keep sealed in a cool, dry cupboard.', 'Use clean, dry utensils to prevent moisture entering the container.', 'published'),
  ('Berbere spice blend', 'berbere-spice-blend', 'Berbere is a complex Ethiopian spice blend whose ingredients and heat vary by maker and region.', 'Spices', null, 'Keep sealed in a cool, dry cupboard away from direct sunlight.', 'Check the ingredient label for allergens and chili heat before serving.', 'published'),
  ('Lemons', 'lemons', 'Lemon juice and zest add bright acidity to savory dishes.', 'Fruit', null, 'Store whole lemons refrigerated for longer keeping; refrigerate cut lemon.', 'Wash the peel before zesting.', 'published'),
  ('Courgette', 'courgette', 'Courgette softens quickly and takes on the flavor of herbs and sauces.', 'Vegetables', null, 'Refrigerate unwashed courgette and wash before preparation.', 'Wash under running water before cutting.', 'published'),
  ('Fresh basil', 'fresh-basil', 'Fresh basil has a sweet, aromatic flavor and is best added near the end of cooking.', 'Herbs', null, 'Keep stems in a glass of water at room temperature or refrigerate loosely wrapped.', 'Wash herbs under running water before use.', 'published'),
  ('Coconut milk', 'coconut-milk', 'Coconut milk adds body and a gentle coconut flavor to curries and soups.', 'Pantry', null, 'Store unopened cans in a cool, dry cupboard; refrigerate opened coconut milk in a covered container.', 'Check the can for damage and refrigerate leftovers promptly.', 'published'),
  ('Flat-leaf parsley', 'flat-leaf-parsley', 'Parsley adds a fresh, green finish to soups, salads, and stews.', 'Herbs', null, 'Refrigerate loosely wrapped and wash just before use.', 'Wash under running water before chopping.', 'published'),
  ('Soy sauce', 'soy-sauce', 'Soy sauce contributes salty, savory flavor to marinades and stir-fries.', 'Condiments', null, 'Refrigerate after opening if directed on the label.', 'Contains soy and often wheat; check the label for allergen information.', 'published'),
  ('Vegetable stock', 'vegetable-stock', 'Vegetable stock provides a savory cooking liquid for grains, soups, and legumes.', 'Pantry', null, 'Refrigerate opened stock and follow its package use-by instructions.', 'Bring stock to a simmer when using in hot dishes; refrigerate leftovers promptly.', 'published'),
  ('Carrots', 'carrots', 'Carrots contribute sweetness and texture to soups and braises.', 'Vegetables', null, 'Refrigerate in a produce drawer.', 'Wash under running water and scrub if needed before cutting.', 'published'),
  ('Hard cheese', 'hard-cheese', 'A small amount of hard cheese adds savory depth to vegetables and eggs.', 'Dairy', null, 'Keep refrigerated and follow the package use-by guidance.', 'Contains milk; use clean utensils and avoid leaving dairy at room temperature for extended periods.', 'published');

insert into public.recipes (
  title, slug, description, cuisine, category, difficulty, prep_time_minutes, cook_time_minutes,
  servings, image_url, educational_info, safety_notes, nutrition_info, status
)
values
  ('Ethiopian Misir Wat', 'ethiopian-misir-wat', 'Red lentils simmered with berbere, onion, and garlic until soft and deeply savory.', 'Ethiopian', 'Plant-based', 'intermediate', 15, 45, 4, '/images/misir-wat.jpg', 'Gentle simmering lets split red lentils soften and thicken the stew. Berbere blends vary by maker and household.', 'Keep dry ingredients and clean utensils separate from ready-to-eat foods. Refrigerate leftovers promptly.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Skillet Shakshuka', 'skillet-shakshuka', 'Eggs gently cooked in a spiced tomato and pepper sauce.', 'North African', 'Vegetarian', 'beginner', 10, 25, 3, '/images/shakshuka.jpg', 'Cooking the pepper and tomato base before adding eggs builds flavor and helps the sauce thicken.', 'Cook eggs until whites are fully set; use pasteurized eggs for preparations that remain raw.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Lemony Lentil Soup', 'lemony-lentil-soup', 'Green lentils, carrots, and aromatics finished with lemon and parsley.', 'Eastern Mediterranean-inspired', 'Plant-based', 'beginner', 15, 40, 4, '/images/lentil-soup.jpg', 'Acidity added near the end brightens the earthy flavor of lentils.', 'Bring soup to a simmer and refrigerate leftovers promptly in shallow covered containers.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Ginger Chicken Stir-fry', 'ginger-chicken-stir-fry', 'Chicken, crisp pepper, ginger, and garlic served with basmati rice.', 'East Asian-inspired', 'Quick meals', 'intermediate', 20, 20, 4, '/images/chicken-stir-fry.jpg', 'Preparing ingredients before heating the pan helps keep a stir-fry moving at high heat.', 'Keep raw chicken separate from ready-to-eat foods and cook it to 74 C / 165 F measured with a food thermometer.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Roasted Vegetable Pasta', 'roasted-vegetable-pasta', 'Pasta tossed with courgette, tomato, olive oil, and fresh basil.', 'Italian-inspired', 'Quick meals', 'beginner', 15, 30, 4, '/images/vegetable-pasta.jpg', 'Roasting vegetables in a single layer encourages browning rather than steaming.', 'Wash produce before cutting and follow package guidance for cooking pasta.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Coconut Chickpea Curry', 'coconut-chickpea-curry', 'Chickpeas and spinach simmered with tomato, cumin, and coconut milk.', 'South Asian-inspired', 'Plant-based', 'beginner', 15, 30, 4, '/images/vegetable-curry.jpg', 'Blooming ground spices briefly in warm oil can deepen their aroma; avoid scorching them.', 'Drain and rinse canned chickpeas with clean water and refrigerate opened ingredients promptly.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Green Lentil Herb Salad', 'green-lentil-herb-salad', 'Green lentils with tomato, onion, parsley, lemon, and olive oil.', 'Levantine-inspired', 'Plant-based', 'beginner', 15, 30, 4, '/images/lentil-soup.jpg', 'Lentils that hold their shape make a satisfying base for a dressed salad.', 'Cool cooked lentils promptly and keep the salad refrigerated until serving.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Tomato Chickpea Stew', 'tomato-chickpea-stew', 'Chickpeas simmered with tomato, garlic, cumin, and parsley.', 'Mediterranean-inspired', 'Plant-based', 'beginner', 10, 30, 4, '/images/misir-wat.jpg', 'Simmering canned tomatoes reduces excess liquid and concentrates their flavor.', 'Use clean utensils and refrigerate leftovers promptly.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Ginger Chicken Rice Bowl', 'ginger-chicken-rice-bowl', 'Ginger-soy chicken served over rice with wilted spinach.', 'East Asian-inspired', 'Quick meals', 'intermediate', 20, 25, 4, '/images/chicken-stir-fry.jpg', 'Cutting ingredients to similar sizes helps them cook at a more even rate.', 'Keep raw chicken separate and verify it reaches 74 C / 165 F with a food thermometer.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published'),
  ('Spinach and Tomato Frittata', 'spinach-tomato-frittata', 'Eggs baked with spinach, tomato, and a little hard cheese.', 'Italian-inspired', 'Vegetarian', 'beginner', 12, 22, 4, '/images/shakshuka.jpg', 'A frittata sets gently when cooked over moderate heat and finished until the center is firm.', 'Cook egg dishes until fully set; refrigerate leftovers promptly.', '{"note":"No numeric nutrition estimate is provided; portions and brands vary. This content is educational, not medical advice."}', 'published');

