insert into public.recipe_steps (recipe_id, step_number, instruction, time_minutes, educational_note)
select r.id, x.step_number, x.instruction, x.time_minutes, x.educational_note
from (values
  ('ethiopian-misir-wat', 1, 'Warm the oil in a heavy pot over medium-low heat. Add the onion and cook, stirring, until soft and translucent.', 10, 'Moderate heat helps onions soften without scorching.'),
  ('ethiopian-misir-wat', 2, 'Add garlic and berbere and stir briefly until fragrant.', 1, 'Spices release aroma in warm oil; lower the heat if they begin to darken quickly.'),
  ('ethiopian-misir-wat', 3, 'Stir in rinsed red lentils and vegetable stock. Bring to a gentle simmer.', 5, 'Rinsing removes loose dust; split red lentils do not need soaking.'),
  ('ethiopian-misir-wat', 4, 'Simmer, stirring occasionally, until the lentils are soft and the stew is thick. Add a little water if needed.', 30, 'Cooking time varies with lentil age and simmer strength.'),
  ('skillet-shakshuka', 1, 'Warm oil in a wide skillet. Soften the onion and pepper over medium heat.', 8, 'Cut vegetables evenly so they soften at a similar rate.'),
  ('skillet-shakshuka', 2, 'Add garlic and cumin and stir until fragrant, then add canned tomatoes.', 2, 'Avoid browning garlic deeply, which can make it bitter.'),
  ('skillet-shakshuka', 3, 'Simmer until the sauce thickens. Make small wells and add the eggs.', 10, 'A thicker sauce helps hold the eggs in place.'),
  ('skillet-shakshuka', 4, 'Cover and cook gently until the egg whites are fully set. Finish with parsley.', 7, 'Use pasteurized eggs for any variation served with a runny center.'),
  ('lemony-lentil-soup', 1, 'Rinse the lentils. Warm a little oil in a pot and soften the onion and carrots.', 8, 'Aromatic vegetables create a savory base before liquid is added.'),
  ('lemony-lentil-soup', 2, 'Add garlic and stir briefly, then add lentils and vegetable stock.', 2, 'Keep garlic moving so it does not scorch.'),
  ('lemony-lentil-soup', 3, 'Bring to a simmer and cook until lentils are tender.', 30, 'Keep the simmer gentle and add water if the soup becomes thicker than desired.'),
  ('lemony-lentil-soup', 4, 'Stir in lemon juice and parsley, then season to taste.', 2, 'Adding acidity at the end preserves its bright flavor.'),
  ('ginger-chicken-stir-fry', 1, 'Cook the rice according to its package instructions. Prepare and separate the raw chicken from vegetables.', 15, 'Use separate boards or wash and sanitize surfaces after raw poultry.'),
  ('ginger-chicken-stir-fry', 2, 'Heat a wide pan. Cook chicken in batches until browned and fully cooked.', 10, 'Do not overcrowd the pan; verify chicken reaches 74 C / 165 F with a thermometer.'),
  ('ginger-chicken-stir-fry', 3, 'Add pepper, ginger, and garlic. Stir-fry until the pepper is crisp-tender.', 4, 'Adding quick-cooking aromatics later helps prevent burning.'),
  ('ginger-chicken-stir-fry', 4, 'Return chicken to the pan, add soy sauce, and stir until hot. Serve with rice.', 2, 'Check condiment labels for allergens such as soy and wheat.'),
  ('roasted-vegetable-pasta', 1, 'Heat the oven to 220 C / 425 F. Toss courgette and tomatoes with olive oil and spread on a tray.', 5, 'A single layer encourages browning instead of steaming.'),
  ('roasted-vegetable-pasta', 2, 'Roast the vegetables until tender and lightly browned.', 20, 'Turn pieces once if the tray browns unevenly.'),
  ('roasted-vegetable-pasta', 3, 'Boil the pasta in salted water according to package instructions, then drain.', 12, 'Reserve a small cup of pasta water before draining if you want a looser sauce.'),
  ('roasted-vegetable-pasta', 4, 'Toss pasta with vegetables and torn basil. Adjust seasoning and serve.', 2, 'Fresh herbs keep more aroma when added near the end.'),
  ('coconut-chickpea-curry', 1, 'Cook the rice according to package instructions. Warm oil in a saucepan.', 15, 'Prepare longer-cooking rice first so it is ready with the curry.'),
  ('coconut-chickpea-curry', 2, 'Add cumin and stir briefly over moderate heat until fragrant.', 1, 'Spices should smell aromatic, not burnt.'),
  ('coconut-chickpea-curry', 3, 'Add tomatoes, coconut milk, and rinsed chickpeas. Simmer until the sauce thickens.', 20, 'A gentle simmer helps the sauce reduce without scorching.'),
  ('coconut-chickpea-curry', 4, 'Fold in spinach until wilted. Serve with rice.', 3, 'Add tender greens at the end to preserve their texture.'),
  ('green-lentil-herb-salad', 1, 'Rinse green lentils, cover with water, and simmer until tender but still holding their shape.', 25, 'Check texture near the end because cooking time varies.'),
  ('green-lentil-herb-salad', 2, 'Drain lentils and spread them in a shallow dish to cool promptly.', 10, 'Shallow layers cool more quickly than a deep pot.'),
  ('green-lentil-herb-salad', 3, 'Combine lentils with tomato, onion, and parsley.', 5, 'Cut ingredients into similar sizes for an even bite.'),
  ('green-lentil-herb-salad', 4, 'Dress with lemon and olive oil. Keep chilled until serving.', 2, 'Taste and adjust acidity gradually.'),
  ('tomato-chickpea-stew', 1, 'Warm olive oil in a saucepan and soften the garlic briefly.', 2, 'Use moderate heat so the garlic remains pale and fragrant.'),
  ('tomato-chickpea-stew', 2, 'Add cumin and tomatoes. Simmer until the tomato base thickens.', 15, 'Reduction concentrates flavor by allowing water to evaporate.'),
  ('tomato-chickpea-stew', 3, 'Stir in drained chickpeas and simmer until hot throughout.', 10, 'Rinsing canned chickpeas can reduce excess brine.'),
  ('tomato-chickpea-stew', 4, 'Finish with parsley and serve warm.', 1, 'Fresh herbs are most aromatic when added just before serving.'),
  ('ginger-chicken-rice-bowl', 1, 'Cook rice according to its package directions and prepare vegetables.', 15, 'Keep raw chicken and ready-to-eat ingredients separate.'),
  ('ginger-chicken-rice-bowl', 2, 'Cook chicken in a hot pan until browned and its center reaches 74 C / 165 F.', 10, 'A food thermometer is more reliable than color for checking poultry doneness.'),
  ('ginger-chicken-rice-bowl', 3, 'Add ginger and soy sauce, then stir until the chicken is coated and hot.', 2, 'Check labels for soy and wheat allergens.'),
  ('ginger-chicken-rice-bowl', 4, 'Wilt spinach in the pan and serve the chicken over rice.', 3, 'Spinach cooks quickly from residual heat.'),
  ('spinach-tomato-frittata', 1, 'Heat the oven to 190 C / 375 F. Soften onion in an oven-safe skillet.', 5, 'A moderate oven helps eggs set without toughening too quickly.'),
  ('spinach-tomato-frittata', 2, 'Add spinach and tomato and cook until the spinach wilts.', 3, 'Remove excess moisture if the tomatoes release a lot of liquid.'),
  ('spinach-tomato-frittata', 3, 'Pour in beaten eggs and sprinkle with cheese if using. Cook briefly on the stovetop.', 3, 'Move cooked egg from the edge toward the center for even setting.'),
  ('spinach-tomato-frittata', 4, 'Bake until the center is fully set. Rest briefly before slicing.', 12, 'Egg dishes should be cooked through; oven times vary by pan and depth.')
) as x(recipe_slug, step_number, instruction, time_minutes, educational_note)
join public.recipes r on r.slug = x.recipe_slug;

insert into public.learning_modules (title, slug, description, category, difficulty, content, status)
values
  ('Red lentils and the texture they make', 'red-lentils-and-texture', 'Learn why split red lentils soften quickly and how that changes soups and stews.', 'ingredients', 'beginner', '{"sections":[{"heading":"Split and whole lentils differ","body":"Red lentils are commonly sold split and often hulled. They soften faster than many whole lentils and can thicken the liquid around them."},{"heading":"Rinse and simmer","body":"Sort and rinse dry lentils, then simmer gently until tender. Older lentils and local growing conditions can change cooking time."}]}', 'published'),
  ('Season aromatics in a pan', 'season-aromatics-in-a-pan', 'Build flavor with onions, garlic, and spices while managing heat carefully.', 'techniques', 'beginner', '{"sections":[{"heading":"Start with the slower ingredients","body":"Onions usually need more time to soften than minced garlic. Add garlic later so it releases aroma without scorching."},{"heading":"Bloom spices gently","body":"Brief contact with warm oil can release spice aromas. Keep the heat moderate and add liquid if spices darken too quickly."}]}', 'published'),
  ('Choose and use a chef knife', 'choose-and-use-a-chef-knife', 'Understand a chef knife shape, a stable board, and controlled cutting habits.', 'tools', 'beginner', '{"sections":[{"heading":"Choose a comfortable tool","body":"A chef knife should feel controllable in your hand. Keep it sharp and use it only for foods suited to the blade."},{"heading":"Stabilize before cutting","body":"Place a damp towel under a cutting board if it slides. Use a tucked-finger claw grip to guide food while keeping fingertips back."}]}', 'published'),
  ('Separate raw poultry and ready-to-eat food', 'separate-raw-poultry-and-ready-to-eat-food', 'Practice conservative habits that reduce cross-contamination when handling poultry.', 'food_safety', 'beginner', '{"sections":[{"heading":"Keep raw poultry separate","body":"Use a dedicated board or plate for raw poultry. Keep its juices away from ready-to-eat food, then wash hands, tools, and surfaces with soap and hot water."},{"heading":"Check doneness with a thermometer","body":"Cook poultry to 74 C / 165 F measured in the thickest part with a food thermometer. Do not rely on color alone, and do not wash raw chicken."}]}', 'published'),
  ('Build a balanced, satisfying plate', 'build-a-balanced-satisfying-plate', 'Explore how vegetables, grains, legumes, and other foods can bring variety to a meal.', 'nutrition', 'beginner', '{"sections":[{"heading":"Think about variety","body":"Combining vegetables or fruit, grains or other starches, and protein foods can add a range of flavors and textures. Needs differ from person to person."},{"heading":"Legumes do more than one job","body":"Beans, peas, and lentils contribute plant protein and dietary fiber. This is general food education, not individualized medical advice."}]}', 'published'),
  ('Berbere and the layers of misir wat', 'berbere-and-the-layers-of-misir-wat', 'Explore berbere spice blends and the lentil technique behind Ethiopian misir wat.', 'world_cuisine', 'intermediate', '{"sections":[{"heading":"Berbere blends vary","body":"Berbere is a complex Ethiopian spice blend. Ingredients, proportions, and heat vary among makers and households; check the blend label before serving."},{"heading":"Build the stew patiently","body":"Misir wat commonly combines lentils with aromatics and seasoned oil. Gentle cooking lets split lentils soften and thicken the stew."}]}', 'published');

insert into public.questions (slug, learning_module_id, question_text, question_type, explanation, difficulty, status)
select x.slug, m.id, x.question_text, 'multiple_choice', x.explanation, x.difficulty::public.difficulty_level, 'published'
from (values
  ('red-lentils-texture', 'red-lentils-and-texture', 'What texture do split red lentils often create when fully simmered?', 'They soften and can thicken the surrounding liquid.', 'beginner'),
  ('rinse-dry-lentils', 'red-lentils-and-texture', 'What is a sensible first step before cooking dry lentils?', 'Sort and rinse them, then follow a suitable cooking method.', 'beginner'),
  ('older-lentils-time', 'red-lentils-and-texture', 'Why might two batches of lentils need different cooking times?', 'Age, variety, and growing conditions can affect how quickly they soften.', 'intermediate'),
  ('aromatics-order', 'season-aromatics-in-a-pan', 'When is minced garlic commonly added when softening onions?', 'After the onions have started to soften, so the garlic is less likely to scorch.', 'beginner'),
  ('spice-bloom', 'season-aromatics-in-a-pan', 'What does briefly warming spices in oil help do?', 'Release aromatic compounds while the cook watches carefully for scorching.', 'beginner'),
  ('scorched-spices', 'season-aromatics-in-a-pan', 'What should you do if spices begin to darken too quickly?', 'Lower the heat and add other ingredients or liquid as appropriate.', 'intermediate'),
  ('cutting-board-stable', 'choose-and-use-a-chef-knife', 'How can you help stop a cutting board sliding on a counter?', 'Place a damp towel beneath it and check that it is stable.', 'beginner'),
  ('knife-claw-grip', 'choose-and-use-a-chef-knife', 'What is the purpose of a tucked-finger claw grip?', 'It helps guide food while keeping fingertips back from the blade.', 'beginner'),
  ('knife-sharp-care', 'choose-and-use-a-chef-knife', 'Which knife habit supports controlled cutting?', 'Keep the blade sharp and use a stable board with controlled strokes.', 'intermediate'),
  ('raw-poultry-separation', 'separate-raw-poultry-and-ready-to-eat-food', 'How should raw poultry be handled around ready-to-eat foods?', 'Keep it separate and use dedicated or thoroughly cleaned utensils and surfaces.', 'beginner'),
  ('poultry-temperature', 'separate-raw-poultry-and-ready-to-eat-food', 'What internal temperature should poultry reach according to the module?', '74 C / 165 F measured with a food thermometer.', 'beginner'),
  ('wash-raw-chicken', 'separate-raw-poultry-and-ready-to-eat-food', 'Should raw chicken be rinsed in the sink before cooking?', 'No. Rinsing can spread droplets; cook it safely and clean hands and surfaces.', 'beginner'),
  ('poultry-doneness-color', 'separate-raw-poultry-and-ready-to-eat-food', 'Why is color alone not a reliable check for poultry doneness?', 'Appearance can vary; a thermometer checks internal temperature directly.', 'intermediate'),
  ('wash-hands-raw-poultry', 'separate-raw-poultry-and-ready-to-eat-food', 'What should you do after handling raw poultry?', 'Wash hands and clean tools and surfaces before handling ready-to-eat food.', 'beginner'),
  ('lentils-cooling', 'separate-raw-poultry-and-ready-to-eat-food', 'How can cooked food be cooled more quickly before refrigeration?', 'Divide it into shallow containers rather than leaving it in a deep pot.', 'intermediate'),
  ('meal-variety', 'build-a-balanced-satisfying-plate', 'What is one practical reason to include a variety of foods in a meal?', 'Different foods can contribute different flavors, textures, and nutrients.', 'beginner'),
  ('legumes-fiber', 'build-a-balanced-satisfying-plate', 'What are lentils commonly known to contribute?', 'Plant protein and dietary fiber.', 'beginner'),
  ('nutrition-individual', 'build-a-balanced-satisfying-plate', 'Should general nutrition learning replace individualized medical advice?', 'No. It is general education and personal needs can differ.', 'beginner'),
  ('plate-rigidity', 'build-a-balanced-satisfying-plate', 'Is there one exact plate composition suitable for every person and context?', 'No. Needs, preferences, and circumstances differ.', 'intermediate'),
  ('whole-food-variety', 'build-a-balanced-satisfying-plate', 'Which approach best describes building a satisfying meal?', 'Consider variety and balance while adapting to the people eating it.', 'beginner'),
  ('berbere-variation', 'berbere-and-the-layers-of-misir-wat', 'Which statement about berbere is most accurate?', 'It is a spice blend whose ingredients and heat can vary by maker and household.', 'beginner'),
  ('misir-wat-lentils', 'berbere-and-the-layers-of-misir-wat', 'Which ingredient is central to misir wat?', 'Lentils simmered with aromatics and seasoning.', 'beginner'),
  ('ethiopian-context', 'berbere-and-the-layers-of-misir-wat', 'How should a learner approach a dish from a food tradition?', 'Learn its ingredients and context while recognizing that practices vary.', 'intermediate'),
  ('blend-label', 'berbere-and-the-layers-of-misir-wat', 'Why check the label on a purchased spice blend?', 'Ingredients and chili heat vary, and the label may identify allergens.', 'beginner'),
  ('injera-context', 'berbere-and-the-layers-of-misir-wat', 'Which grain is commonly associated with injera in Ethiopian cooking?', 'Teff is commonly used, though preparations and ingredients can vary.', 'intermediate'),
  ('oil-medium-heat', 'season-aromatics-in-a-pan', 'Why use moderate heat when first adding spices to oil?', 'It gives aromas time to release and reduces the chance of burning.', 'beginner'),
  ('stir-fry-batches', 'season-aromatics-in-a-pan', 'Why cook a crowded stir-fry in batches?', 'Crowding can lower pan heat and encourage ingredients to steam.', 'intermediate'),
  ('knife-cut-consistency', 'choose-and-use-a-chef-knife', 'Why cut vegetables into pieces of similar size?', 'Similar sizes tend to cook at a more similar rate.', 'beginner'),
  ('food-thermometer', 'separate-raw-poultry-and-ready-to-eat-food', 'Where should you measure the temperature of a large poultry piece?', 'In the thickest part, avoiding bone where possible.', 'intermediate'),
  ('flavor-acidity', 'build-a-balanced-satisfying-plate', 'What can a little lemon juice do in a lentil dish?', 'Its acidity can brighten flavor; add gradually and taste.', 'beginner')
) as x(slug, module_slug, question_text, explanation, difficulty)
join public.learning_modules m on m.slug = x.module_slug;

