insert into public.daily_challenges (challenge_date, title, slug, description, challenge_type, recipe_id, learning_module_id, ingredient_id, status)
select x.challenge_date::date, x.title, x.slug, x.description, x.challenge_type::public.daily_challenge_type,
  r.id, m.id, i.id, 'published'
from (values
  ('2026-10-01', 'Find the gentle simmer', 'find-the-gentle-simmer-2026-10-01', 'Read the lentil method and identify why a gentle simmer helps preserve texture.', 'recipe', 'ethiopian-misir-wat', null, null),
  ('2026-10-02', 'Layer aromatics with care', 'layer-aromatics-with-care-2026-10-02', 'Review when garlic is added and how to keep spices from scorching.', 'learning_module', null, 'season-aromatics-in-a-pan', null),
  ('2026-10-03', 'Know your lentils', 'know-your-lentils-2026-10-03', 'Compare split red lentils with whole green lentils and their cooking textures.', 'ingredient', null, null, 'red-lentils'),
  ('2026-10-04', 'Build the tomato base', 'build-the-tomato-base-2026-10-04', 'Explore how a tomato sauce thickens before eggs are added.', 'recipe', 'skillet-shakshuka', null, null),
  ('2026-10-05', 'Separate and check', 'separate-and-check-2026-10-05', 'Review separate preparation for raw poultry and use a thermometer for doneness.', 'learning_module', null, 'separate-raw-poultry-and-ready-to-eat-food', null)
) as x(challenge_date, title, slug, description, challenge_type, recipe_slug, module_slug, ingredient_slug)
left join public.recipes r on r.slug = x.recipe_slug
left join public.learning_modules m on m.slug = x.module_slug
left join public.ingredients i on i.slug = x.ingredient_slug;
